const upsertForumVote = `-- name: UpsertForumVote :one

INSERT INTO forum_votes (tenant_id, user_id, entity_type, entity_id, value)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (user_id, entity_type, entity_id) DO UPDATE
    SET value = $5
RETURNING id, tenant_id, user_id, entity_type, entity_id, value, created_at
`

type UpsertForumVoteParams struct {
	TenantID   pgtype.UUID `json:"tenant_id"`
	UserID     pgtype.UUID `json:"user_id"`
	EntityType string      `json:"entity_type"`
	EntityID   pgtype.UUID `json:"entity_id"`
	Value      int16       `json:"value"`
}

// =====================
// Votes
// =====================
func (q *Queries) UpsertForumVote(ctx context.Context, arg UpsertForumVoteParams) (ForumVote, error) {
	row := q.db.QueryRow(ctx, upsertForumVote,
		arg.TenantID,
		arg.UserID,
		arg.EntityType,
		arg.EntityID,
		arg.Value,
	)
	var i ForumVote
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.UserID,
		&i.EntityType,
		&i.EntityID,
		&i.Value,
		&i.CreatedAt,
	)
	return i, err
}

const voteForumPoll = `-- name: VoteForumPoll :one
INSERT INTO forum_poll_votes (poll_id, option_id, user_id)
VALUES ($1, $2, $3)
ON CONFLICT (option_id, user_id) DO UPDATE
    SET created_at = now()
RETURNING id, poll_id, option_id, user_id, created_at
`

type VoteForumPollParams struct {
	PollID   pgtype.UUID `json:"poll_id"`
	OptionID pgtype.UUID `json:"option_id"`
	UserID   pgtype.UUID `json:"user_id"`
}

// Casts a vote for a single poll option. The unique constraint is on
// (option_id, user_id) to support multi-select polls (BUG-002). For
// single-select polls the service clears the user's existing votes first.
func (q *Queries) VoteForumPoll(ctx context.Context, arg VoteForumPollParams) (ForumPollVote, error) {
	row := q.db.QueryRow(ctx, voteForumPoll, arg.PollID, arg.OptionID, arg.UserID)
	var i ForumPollVote
	err := row.Scan(
		&i.ID,
		&i.PollID,
		&i.OptionID,
		&i.UserID,
		&i.CreatedAt,
	)
	return i, err
}
